package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class ApplyOwner {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request) {
        owner.setAddressLine1(request.getAddressLine1());
        owner.setAddressLine2(request.getAddressLine2());
        // Prefer the structured form: when addressLine1 is supplied the stored flat address is
        // the composed value; otherwise the backward-compatible flat address is used as given.
        String line1 = request.getAddressLine1();
        if (line1 != null && !line1.isBlank()) {
            owner.setAddress(AddressNormalizer.compose(line1, request.getAddressLine2()));
        }
        else {
            owner.setAddress(request.getAddress());
        }
        owner.setCity(request.getCity());
        owner.setFirstName(request.getFirstName());
        owner.setLastName(request.getLastName());
        owner.setTelephone(request.getTelephone());
        owner.setEmail(request.getEmail());
        owner.setPostcode(request.getPostcode());
    }
}
